// === Tab: mySketch ===
let myFilter

function setup() {
  createCanvas(windowWidth, windowWidth*.75, WEBGL);
  background(0);
  window.simulatedMouseX = width/2;
  window.simulatedMouseY = height/2;	
  myFilter = createFilterShader(`
    precision mediump float;

    uniform sampler2D tex0;
    varying vec2 vTexCoord;

    uniform float time;

    void main() {
      float scaleX = sin(time * 0.5) * 20.0 + 80.0;
      float scaleY = sin(time * 0.4) * 40.0 + 60.0;
      vec2 coord = (vTexCoord - 0.5) * 0.99 + 0.5;
      coord.x += 0.0005 * sin(coord.y * scaleX + time);
      coord.x += 0.001 * sin(coord.y * 0.1 * scaleX + time);
      coord.y += 0.0005 * sin(coord.x * scaleY + time * 0.8);
      coord.y += 0.001 * sin(coord.x * 0.1 * scaleY + time * 0.8);
      gl_FragColor = mix(
        texture2D(tex0, coord) * vec4(abs(sin(time*.1)) * 0.9999, abs(sin(1.0 + time*.1)) * 0.9999, abs(sin(2.0 + time*.1)) * 0.9999, 1.0),
        vec4(0.0, 0.0, 0.0, 1.0),
        0.01
      );
    }
  `)
}

function draw() {
  myFilter.setUniform('time', millis() * 0.001)
  filter(myFilter)
  noStroke()
  // normalMaterial()
  fill('#FFFFFF')
  push()
  blendMode(ADD)
  translate((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - width/2, (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - height/2)
  circle(0, 0, 100)
  pop()
}

function keyPressed(){
  save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
}

